function makeSurvivorFigure(who) {
  const look = SURVIVOR_LOOK[who] || SURVIVOR_LOOK.okafor;
  const m = makeMarine();
  const st = WARDROBE_LISTS.defaultWardrobe('m81');
  st.items.cap.style = look.cap;
  st.items.eyewear = { style: look.eyewear };
  st.items.shirt.sleeves = look.sleeves;
  st.items.gloves.worn = look.gloves;
  st.body = { skin: look.skin, hair: look.hair, eyes: look.eyes };
  dressMarine(m, st);
  const gp = m.userData.gearParts;
  for (const k of Object.keys(gp)) for (const o of gp[k]) o.visible = look.gear.includes(k);
  if (!survivorKitMats) survivorKitMats = {
    olive: new THREE.MeshStandardMaterial({ color: 0x4f5a34, roughness: 0.9 }),
    white: new THREE.MeshStandardMaterial({ color: 0xe8e4d8, roughness: 0.8 }),
    brass: new THREE.MeshStandardMaterial({ color: 0xb8913c, roughness: 0.35, metalness: 0.8 }),
    link: new THREE.MeshStandardMaterial({ color: 0x2c2c28, roughness: 0.5, metalness: 0.6 }),
    steel: new THREE.MeshStandardMaterial({ color: 0x8d9094, roughness: 0.35, metalness: 0.85 })
  };
  const K = survivorKitMats, hip = m.userData.hip, torso = m.userData.torsoG;
  const geos = [];
  const box = (parent, w, h, d, mat, x, y, z, rx = 0, ry = 0, rz = 0) => {
    const g = new THREE.BoxGeometry(w, h, d); geos.push(g);
    const o = new THREE.Mesh(g, mat); o.position.set(x, y, z); o.rotation.set(rx, ry, rz); o.castShadow = true; parent.add(o); return o;
  };
  if (look.kit === 'aidBag' && hip) {
    const bag = new THREE.Group(); bag.name = 'survivor-aid-bag'; bag.position.set(0.25, 0.0, 0.04); hip.add(bag);
    const body=rmesh(.13,.24,.23,K.olive,.038);bag.add(body);geos.push(body.geometry);
    const band=rmesh(.135,.039,.236,K.white,.017);band.position.y=.037;bag.add(band);geos.push(band.geometry);
    box(bag,.025,.15,.02,K.olive,-.037,.158,-.045);
    box(bag,.025,.15,.02,K.olive,.037,.158,-.045);
  }
  if (look.kit === 'belt' && torso) {
    const belt = new THREE.Group(); belt.name = 'survivor-ammo-belt'; torso.add(belt);
    const path=new THREE.CatmullRomCurve3([[-.16,.43,.208],[0,.23,.256],[.16,.03,.208],[.18,.015,0],[.16,.04,-.16],[0,.24,-.17],[-.16,.43,-.15],[-.16,.45,0]].map(p=>new THREE.Vector3(...p)),true);
    const verts=[],uv=[],idx=[];
    for(let j=0;j<=48;j++){const p=path.getPointAt(j/48);for(const s of[-1,1]){verts.push(p.x+s*.021,p.y+s*.016,p.z);uv.push((s+1)/2,j/48);}}
    for(let j=0;j<48;j++){const a=j*2;idx.push(a,a+1,a+2,a+1,a+3,a+2);}K.link.side=THREE.DoubleSide;
    const web=new THREE.BufferGeometry();web.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));web.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));web.setIndex(idx);web.computeVertexNormals();geos.push(web);belt.add(addCast(new THREE.Mesh(web,K.link)));
    for (let i = 0; i < 12; i++) {
      const u=i/11,x=-.16+.32*u,y=.43-.4*u,z=.208+.048*Math.sin(Math.PI*u);
      const geo=new THREE.CylinderGeometry(.009,.012,.064,8);geos.push(geo);const round=addCast(new THREE.Mesh(geo,K.brass));round.position.set(x,y,z+.013);round.rotation.z=-.9;belt.add(round);
      box(belt,.037,.012,.02,K.link,x+.014,y-.017,z+.015,0,0,-.9);
    }
  }
  if (look.kit === 'wrench' && hip) {
    const w = new THREE.Group(); w.name = 'survivor-wrench'; w.position.set(-0.24, -0.04, 0.06); w.rotation.z = 0.15; hip.add(w);
    box(w, 0.03, 0.3, 0.012, K.steel, 0, -0.08, 0);
    box(w, 0.07, 0.05, 0.014, K.steel, 0, 0.07, 0);
  }
  if (look.rifle && torso && weaponMeshes.m4) {
    const r = weaponMeshes.m4.clone(); r.name = 'survivor-rifle';
    r.position.set(0.02, 0.22, -0.2); r.rotation.set(0, Math.PI / 2, 0.85);   // slung across the back
    r.visible = true; torso.add(r);
  }
  // The survivors expose the actual tapered head: no mask fragments and
  // no cover-up boxes. Their existing skin, hair and eye choices still apply.
  const d = m.userData.dress, headG = m.userData.headG, HP = m.userData.headPivotY || 1.22;
  if (d && headG) {
    for (const o of m.userData.wardrobe.mask.meshes) o.visible = false;
    m.userData.bareFaceDetails.visible = true;
    const face = (w, h, depth, mat, x, y, z) => {
      const o = rmesh(w, h, depth, mat, Math.min(h, depth) * .4);
      o.position.set(x, y - HP, z);headG.add(o);return o;
    };
    if (!survivorKitMats.mouth) survivorKitMats.mouth = new THREE.MeshStandardMaterial({ color: 0x513a30, roughness: 1 });
    face(.052, .006, .007, survivorKitMats.mouth, 0, 1.348, .154).name = 'survivor-mouth';
    face(.041, .008, .01, d.mats.skin, 0, 1.338, .153);
    if (who === 'brandt') {
      const beard = buildSurvivorBeard(THREE, d.mats.hair);headG.add(beard);geos.push(beard.geometry);
      for (const sx of [-1, 1]) {
        const moustache = face(.038, .011, .011, d.mats.hair, sx * .023, 1.36, .155);
        moustache.rotation.z = -sx * .16;
      }
    }
  }
  m.userData.survivorWho = who;
  m.userData.survivorGeos = geos;
  return m;
}

      // Face (CL-32, Jerry): what shows above the mask when he has no helmet or goggles on.
      // Eyes with whites, brown irises, pupils and a catchlight, set in shaded sockets under
      // heavy lids; brows angled down at the middle; a nose bridge, cheekbones, sideburns,
      // and an old scar through the left brow.
      const skinShade = new THREE.MeshStandardMaterial({ color: 0x9c7f5e, roughness: 0.9 });
      const scarMat = new THREE.MeshStandardMaterial({ color: 0xcfb28e, roughness: 0.6 });
      dress.mats.skinShade = skinShade; dress.mats.scar = scarMat;
      const glintMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
      const eyeMat = new THREE.MeshBasicMaterial({ color: 0x0a0a0a });
      const hRot = (mesh, rx, ry, rz) => { mesh.rotation.set(rx, ry, rz); return mesh; };
      for (const sx of [-1, 1]) {
        const ex = sx * 0.06;
        hAdd(rmesh(0.06, 0.033, 0.01, skinShade, 0.009), ex, 1.419, 0.144);                    // restrained socket shadow
        hAdd(rmesh(0.044, 0.019, 0.01, jawPrint, 0.008), ex, 1.419, 0.148);                   // white of the eye
        hAdd(rmesh(0.018, 0.018, 0.007, irisW, 0.007), ex - sx * 0.002, 1.419, 0.153);        // iris
        hAdd(new THREE.Mesh(rbox(0.009, 0.01, 0.005, 0.003), eyeMat), ex - sx * 0.002, 1.419, 0.156);  // pupil
        hAdd(new THREE.Mesh(rbox(0.003, 0.003, 0.002, 0.001), glintMat), ex - sx * 0.002 + 0.003, 1.422, 0.159); // catchlight
        hRot(hAdd(rmesh(0.049, 0.008, 0.01, skinW, 0.0035), ex, 1.43, 0.152), 0.2, 0, 0);   // upper lid
        hAdd(rmesh(0.044, 0.005, 0.007, skinShade, 0.0025), ex, 1.4075, 0.15);                // lower lid
        hRot(hAdd(rmesh(0.055, 0.009, 0.011, hairW, 0.004), ex + sx * 0.002, 1.45, 0.153), 0, 0, sx * 0.1); // brow
        hAdd(rmesh(0.03, 0.009, 0.008, skinW, 0.004), sx * 0.082, 1.398, 0.13);               // cheekbone blends into the head
        bareAdd(rmesh(0.018, 0.06, 0.035, hairW, 0.006), sx * 0.127, 1.405, 0.045);             // sideburn
        bareAdd(rmesh(0.012, 0.035, 0.02, skinShade, 0.005), sx * 0.142, 1.4, 0.0);               // inner ear
      }
      hAdd(rmesh(0.01, 0.008, 0.007, skinShade, 0.003), 0, 1.441, 0.151);                    // frown crease
      hRot(hAdd(rmesh(0.004, 0.027, 0.003, scarMat, 0.0015), -0.076, 1.445, 0.16), 0, 0, 0.3); // scar through the left brow
      // Jerry: a fitted cloth balaclava, always worn by the player. Every
      // surface uses maskW so the entire hood follows the existing camo item.
      headG.add(buildBalaclava(THREE, maskW));

      // CL-97: eyewear, over the eyes above the mask (Jerry: aviators, a pit-viper style, a Wayfarer style, the GWOT
      // ballistic goggles). Hidden while the NVG is down (updateMarineBody).
      const eyeG = new THREE.Group();
      eyeG.position.y = -HEAD_PIVOT_Y;
      headG.add(eyeG);
      const E = eyewearMats;
      dress.eyes.none = part(eyeG);
      const avi = dress.eyes.aviators = part(eyeG);
      for (const sx of [-1, 1]) {
        put(avi, rmesh(0.08, 0.068, 0.006, E.gold, 0.028), sx * 0.06, 1.413, 0.176, 0, 0, sx * -0.14);      // rim
        put(avi, rmesh(0.074, 0.062, 0.009, E.aviLens, 0.026), sx * 0.06, 1.411, 0.179, 0, 0, sx * -0.14);  // teardrop lens
        put(avi, rmesh(0.006, 0.006, 0.15, E.gold, 0.002), sx * 0.13, 1.432, 0.1);                          // temple
      }
      put(avi, rmesh(0.05, 0.005, 0.005, E.gold, 0.002), 0, 1.437, 0.18);                                  // double bridge
      put(avi, rmesh(0.03, 0.005, 0.005, E.gold, 0.002), 0, 1.424, 0.18);
      const viper = dress.eyes.pitViper = part(eyeG);
      put(viper, rmesh(0.2, 0.062, 0.01, E.viperLens, 0.02), 0, 1.42, 0.182);                              // the shield
      put(viper, rmesh(0.214, 0.02, 0.018, E.viperFrame, 0.008), 0, 1.456, 0.18);                          // top bar
      for (const sx of [-1, 1]) {
        put(viper, rmesh(0.045, 0.058, 0.009, E.viperLens, 0.016), sx * 0.112, 1.42, 0.16, 0, sx * 0.75, 0);   // wrap
        put(viper, rmesh(0.012, 0.022, 0.15, E.viperFrame, 0.006), sx * 0.132, 1.44, 0.07);                  // thick temple
      }
      const way = dress.eyes.wayfarer = part(eyeG);
      for (const sx of [-1, 1]) {
        put(way, rmesh(0.074, 0.05, 0.012, E.wayFrame, 0.01), sx * 0.058, 1.422, 0.177, 0, 0, sx * 0.06);     // frame
        put(way, rmesh(0.058, 0.036, 0.006, E.wayLens, 0.008), sx * 0.058, 1.418, 0.184, 0, 0, sx * 0.06);    // lens
        put(way, rmesh(0.012, 0.016, 0.15, E.wayFrame, 0.005), sx * 0.13, 1.44, 0.1);                         // temple
      }
      put(way, rmesh(0.16, 0.016, 0.014, E.wayFrame, 0.006), 0, 1.448, 0.178);                              // the heavy brow line
      put(way, rmesh(0.026, 0.012, 0.012, E.wayFrame, 0.004), 0, 1.428, 0.179);                             // bridge
      const gog = dress.eyes.goggles = part(eyeG);
      put(gog, rmesh(0.235, 0.072, 0.04, E.gogFrame, 0.02), 0, 1.425, 0.17);                                // foam frame
      put(gog, rmesh(0.214, 0.056, 0.01, E.gogLens, 0.016), 0, 1.426, 0.192);                               // one wide lens
      put(gog, rmesh(0.04, 0.02, 0.012, E.gogFrame, 0.006), 0, 1.395, 0.19);                               // nose cut
      put(gog, rmesh(0.278, 0.03, 0.33, E.gogStrap, 0.01), 0, 1.44, 0.0);                                   // strap round the head
      g.userData.eyewearG = eyeG;
